from pathlib import Path
import re

main = Path('app/src/main/java/tr/borsatakip/v3/MainActivity.kt')
s = main.read_text(encoding='utf-8')

# Keep previous results visible during a new scan and move heavy scoring off the UI thread.
s = s.replace('private fun beginScanUi(button:ScanButton,title:String){adapter.submitList(emptyList());showContent();', 'private fun beginScanUi(button:ScanButton,title:String){showContent();')
s = s.replace('private fun finishFailure(error:Throwable){adapter.submitList(emptyList());binding.progressBar.progress=0;', 'private fun finishFailure(error:Throwable){binding.progressBar.progress=0;')
s = s.replace('import kotlinx.coroutines.Job\n', 'import kotlinx.coroutines.Job\nimport kotlinx.coroutines.Dispatchers\nimport kotlinx.coroutines.withContext\n')
s = s.replace('val all=result.items.mapNotNull(scoring::score); binding.statusText.text="ANALİZ EDİLİYOR...";', 'val all=withContext(Dispatchers.Default){result.items.mapNotNull(scoring::score)}; binding.statusText.text="ANALİZ EDİLİYOR...";')
s = s.replace('val rows=b.items.mapNotNull(scoring::score); binding.progressBar.progress=80', 'val rows=withContext(Dispatchers.Default){b.items.mapNotNull(scoring::score)}; binding.progressBar.progress=80')

# BIST + VIOP are requested in parallel. If VIOP is unavailable, do not erase valid BIST opportunities.
start='    private fun startCombinedOpportunityScan() {'
end='    private fun beginScanUi(button:ScanButton,title:String)'
i=s.find(start); j=s.find(end,i)
if i!=-1 and j!=-1:
    block='''    private fun startCombinedOpportunityScan() {\n        if (scanJob?.isActive == true) return\n        beginScanUi(ScanButton.OPPORTUNITY,"FIRSAT KONTROLÜ"); selectNav(1)\n        scanJob=lifecycleScope.launch {\n            binding.statusText.text="BIST + VİOP VERİLERİ AYNI ANDA ALINIYOR..."; binding.progressBar.progress=10\n            try {\n                val (br,vr)=coroutineScope { async { provider.loadMarket(Market.BIST) } to async { provider.loadMarket(Market.VIOP) } }\n                val b=br.await().getOrElse{throw it}; binding.progressBar.progress=50\n                val vResult=vr.await(); binding.progressBar.progress=65\n                val allItems=b.items + (vResult.getOrNull()?.items ?: emptyList())\n                binding.statusText.text="BIST + VİOP ANALİZ EDİLİYOR..."\n                val rows=withContext(Dispatchers.Default){allItems.mapNotNull(scoring::score)}\n                val visible=rows.filter{it.direction!="SİNYAL YOK"&&it.score>=70}.sortedByDescending{it.score}\n                val v= vResult.getOrNull()\n                val source=if(v!=null) listOf(b.sourceName,v.sourceName).distinct().joinToString(" + ") else "${b.sourceName} • VİOP veri kaynağı yok"\n                finishSuccess(visible,maxOf(b.dataTimestamp,v?.dataTimestamp ?: 0L),source,true, v==null)\n            } catch(t:Throwable){finishFailure(t)}\n        }\n    }\n\n'''
    s=s[:i]+block+s[j:]
else:
    raise SystemExit('combined scan anchors not found')

# Add a small market-status state instead of permanently showing "VERİ BEKLENİYOR".
s=s.replace('private var scanJob: Job? = null', 'private var scanJob: Job? = null\n    private var watchLoadJob: Job? = null\n    private var watchQuotes: Map<String, Opportunity> = emptyMap()')
s=s.replace('private fun finishSuccess(visible:List<Opportunity>,dataTimestamp:Long,sourceName:String,combined:Boolean=false){', 'private fun finishSuccess(visible:List<Opportunity>,dataTimestamp:Long,sourceName:String,combined:Boolean=false,partial:Boolean=false){')
s=s.replace('binding.progressBar.progress=100;adapter.submitList(visible);', 'binding.progressBar.progress=100;adapter.submitList(visible);binding.marketStatus.text=if(partial)"● KISMİ VERİ" else "● VERİ ALINDI";binding.marketStatus.setTextColor(if(partial)Color.parseColor("#D99000") else Color.parseColor("#0A9F63"));')
s=s.replace('private fun finishFailure(error:Throwable){binding.progressBar.progress=0;', 'private fun finishFailure(error:Throwable){binding.progressBar.progress=0;binding.marketStatus.text="● BAĞLANTI YOK";binding.marketStatus.setTextColor(Color.parseColor("#D9304F"));')

# Replace the old watchlist renderer with a compact quote-aware list.
ws=s.find('private fun showWatchlist(){')
we=s.find('private fun showInfo(title:String,body:String){', ws)
if ws!=-1 and we!=-1:
    watch='''private fun showWatchlist(){\nscanJob?.cancel();scanJob=null;watchLoadJob?.cancel();restoreButtons();showContent();binding.titleText.text="Takip Listem";binding.subtitleText.text="Canlı fiyat • değişim • yön";binding.progressBar.visibility=View.GONE;binding.recyclerView.visibility=View.GONE;binding.statusText.text="Takip hisseleri yükleniyor...";binding.watchActionRow.visibility=View.VISIBLE;binding.watchListContainer.visibility=View.VISIBLE;binding.addWatchButton.setOnClickListener{addWatchSymbol()};binding.clearWatchButton.setOnClickListener{clearWatchlist()};renderWatchlist();refreshWatchlistQuotes();selectNav(3)\n}\nprivate fun refreshWatchlistQuotes(){\nval symbols=getSharedPreferences("watchlist",MODE_PRIVATE).getStringSet("symbols",emptySet())?.toList()?:emptyList();if(symbols.isEmpty()){watchQuotes=emptyMap();renderWatchlist();return};watchLoadJob=lifecycleScope.launch{provider.loadMarket(Market.BIST).onSuccess{result->watchQuotes=result.items.mapNotNull{runCatching{scoring.score(it)}.getOrNull()}.filter{symbols.contains(it.symbol)}.associateBy{it.symbol};renderWatchlist();binding.statusText.text="${watchQuotes.size}/${symbols.size} takip hissesi için veri alındı. ${freshnessLabel(result.dataTimestamp)}"}.onFailure{renderWatchlist();binding.statusText.text="Fiyat verisi alınamadı. API bağlantısını kontrol edin."}}\n}\nprivate fun renderWatchlist(){\nval symbols=getSharedPreferences("watchlist",MODE_PRIVATE).getStringSet("symbols",emptySet())?.toList()?.sorted()?:emptyList();binding.watchListContainer.removeAllViews();if(symbols.isEmpty()){val empty=android.widget.TextView(this);empty.text="Henüz takip edilen hisse bulunmuyor.\\n\\nÖrneğin: THYAO, ASELS, TUPRS";empty.setTextColor(Color.parseColor("#5D6B78"));empty.textSize=15f;empty.setPadding(16,24,16,24);binding.watchListContainer.addView(empty);return};symbols.forEach{symbol->val q=watchQuotes[symbol];val row=android.widget.LinearLayout(this);row.orientation=android.widget.LinearLayout.HORIZONTAL;row.gravity=android.view.Gravity.CENTER_VERTICAL;row.setPadding(10,10,6,10);row.background=androidx.appcompat.content.res.AppCompatResources.getDrawable(this,tr.borsatakip.v3.R.drawable.bg_surface);val name=android.widget.TextView(this);name.text="★ $symbol";name.textSize=16f;name.setTypeface(null,android.graphics.Typeface.BOLD);name.setTextColor(Color.parseColor("#17212B"));row.addView(name,android.widget.LinearLayout.LayoutParams(0,android.widget.LinearLayout.LayoutParams.WRAP_CONTENT,1.0f));val quote=android.widget.TextView(this);quote.text=if(q==null)"Veri bekleniyor" else "${fmt(q.price)}\\n${q.direction}";quote.gravity=android.view.Gravity.END;quote.textSize=14f;quote.setTypeface(null,android.graphics.Typeface.BOLD);quote.setTextColor(if(q?.direction=="LONG")Color.parseColor("#0A9F63") else if(q?.direction=="SHORT")Color.parseColor("#D9304F") else Color.parseColor("#5D6B78"));row.addView(quote,android.widget.LinearLayout.LayoutParams(0,android.widget.LinearLayout.LayoutParams.WRAP_CONTENT,1.0f));val del=android.widget.Button(this);del.text="SİL";del.setTextSize(11f);del.minWidth=0;del.setPadding(10,0,10,0);del.setOnClickListener{removeWatchSymbol(symbol)};row.addView(del,android.widget.LinearLayout.LayoutParams(android.widget.LinearLayout.LayoutParams.WRAP_CONTENT,52));val lp=android.widget.LinearLayout.LayoutParams(android.widget.LinearLayout.LayoutParams.MATCH_PARENT,android.widget.LinearLayout.LayoutParams.WRAP_CONTENT);lp.setMargins(0,6,0,0);binding.watchListContainer.addView(row,lp)}}\nprivate fun addWatchSymbol(){\nval symbols=listOf("AEFES","AKBNK","AKSEN","ALARK","ALBRK","ALFAS","ARCLK","ASELS","ASTOR","AYDEM","BIMAS","BRSAN","CCOLA","CIMSA","DOAS","DOHOL","ECILC","ECZYT","EKGYO","ENKAI","EREGL","EUPWR","FROTO","GARAN","GESAN","GUBRF","HALKB","HEKTS","ISCTR","ISDMR","ISMEN","KARSN","KCHOL","KONTR","KOZAA","KOZAL","KRDMD","MAVI","MGROS","MIATK","ODAS","OYAKC","PASEU","PETKM","PGSUS","PETUN","SAHOL","SASA","SISE","SKBNK","SMRTG","TAVHL","TCELL","THYAO","TKFEN","TOASO","TRALT","TTKOM","TTRAK","TUPRS","TURSG","ULKER","VAKBN","VESBE","VESTL","YKBNK","YYLGD")\nval input=android.widget.AutoCompleteTextView(this);input.hint="Hisse kodunu yazın veya listeden seçin";input.inputType=android.text.InputType.TYPE_CLASS_TEXT or android.text.InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS;input.threshold=0;input.setAdapter(android.widget.ArrayAdapter(this,android.R.layout.simple_dropdown_item_1line,symbols));input.setOnFocusChangeListener{_,hasFocus->if(hasFocus)input.post{input.showDropDown()}};input.setOnClickListener{input.post{input.showDropDown()}};input.addTextChangedListener(object:android.text.TextWatcher{override fun beforeTextChanged(s:CharSequence?,start:Int,count:Int,after:Int){};override fun onTextChanged(s:CharSequence?,start:Int,before:Int,count:Int){input.post{input.showDropDown()}};override fun afterTextChanged(s:android.text.Editable?){}});input.setOnItemClickListener{_,_,position,_->input.setText(input.adapter.getItem(position).toString());input.setSelection(input.text.length);input.dismissDropDown()};val dialog=android.app.AlertDialog.Builder(this).setTitle("Takip Listesine Hisse Ekle").setView(input).setNegativeButton("İPTAL",null).setPositiveButton("EKLE"){_,_->val symbol=input.text.toString().trim().uppercase(Locale("tr","TR"));if(symbol.isBlank())return@setPositiveButton;val prefs=getSharedPreferences("watchlist",MODE_PRIVATE);val set=prefs.getStringSet("symbols",emptySet())?.toMutableSet()?:mutableSetOf();set.add(symbol);prefs.edit().putStringSet("symbols",set).apply();renderWatchlist();refreshWatchlistQuotes()}.create();dialog.setOnShowListener{input.requestFocus();dialog.window?.setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE);input.postDelayed{input.showDropDown()}};dialog.show()\n}\nprivate fun removeWatchSymbol(symbol:String){val prefs=getSharedPreferences("watchlist",MODE_PRIVATE);val set=prefs.getStringSet("symbols",emptySet())?.toMutableSet()?:mutableSetOf();set.remove(symbol);prefs.edit().putStringSet("symbols",set).apply();watchQuotes=watchQuotes-filterKeys(set);renderWatchlist()}\nprivate fun filterKeys(set:Set<String>):Map<String,Opportunity>{return watchQuotes.filterKeys{set.contains(it)}}\nprivate fun clearWatchlist(){getSharedPreferences("watchlist",MODE_PRIVATE).edit().clear().apply();watchQuotes=emptyMap();renderWatchlist()}\n'''
    s=s[:ws]+watch+s[we:]
else:
    raise SystemExit('watchlist anchors not found')

# Reset connection status on home.
s=s.replace('binding.lastScanHome.text="Henüz tarama yapılmadı.";', 'binding.lastScanHome.text="Henüz tarama yapılmadı.";binding.marketStatus.text="● VERİ BEKLENİYOR";binding.marketStatus.setTextColor(Color.parseColor("#D99000"));')

# Faster backend timeouts and explicit no-cache headers.
provider=Path('app/src/main/java/tr/borsatakip/v3/market/LiveBackendMarketDataProvider.kt')
p=provider.read_text(encoding='utf-8')
p=p.replace('connectTimeout = 10_000','connectTimeout = 5_000').replace('readTimeout = 20_000','readTimeout = 8_000')
p=p.replace('setRequestProperty("Accept", "application/json")','setRequestProperty("Accept", "application/json")\n                setRequestProperty("Cache-Control", "no-cache")')
provider.write_text(p,encoding='utf-8')

# V4 version.
gradle=Path('app/build.gradle.kts')
g=gradle.read_text(encoding='utf-8').replace('versionCode = 40','versionCode = 41').replace('versionName = "4.0.0"','versionName = "4.0.1"')
gradle.write_text(g,encoding='utf-8')
